mapper.select:
SELECT id, conversation_id, employee_id, role, joined_at, left_at,
       last_read_message_id, last_read_at, is_muted, is_pinned,
       created_at, updated_at, deleted_at, delete_flag
FROM conversation_participants
WHERE conversation_id = #{conversationId}
  AND employee_id = #{employeeId}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

mapper.update:
UPDATE conversation_participants
SET is_muted = COALESCE(#{isMuted}, is_muted),
    is_pinned = COALESCE(#{isPinned}, is_pinned),
    updated_at = CURRENT_TIMESTAMP
WHERE conversation_id = #{conversationId}
  AND employee_id = #{employeeId}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

UPDATE conversation_participants
SET last_read_message_id = #{lastReadMessageId},
    last_read_at = CURRENT_TIMESTAMP,
    updated_at = CURRENT_TIMESTAMP
WHERE conversation_id = #{conversationId}
  AND employee_id = #{employeeId}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

UPDATE conversation_participants
SET delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@DELETED.value},
    left_at = CURRENT_TIMESTAMP,
    deleted_at = CURRENT_TIMESTAMP
WHERE conversation_id = #{conversationId}
  AND employee_id = #{employeeId}

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM conversation_participants
    WHERE conversation_id = #{conversationId}
      AND employee_id = #{employeeId}
      AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
)
